mapper.select:
SELECT d.status AS status, COUNT(*) AS cnt
FROM workstudy_post d
WHERE d.deleted = 0
AND d.academic_term = #{academicTerm}
AND d.unit_user_id = #{unitUserId}
GROUP BY d.status
